function C:isAppOpen(app)
  local window = self.WindowList:Find(function(l) return l.appType == app end)
  if window == nil then
    return false
  end
  if window.windowState == "minimized" or window.windowState == "closed" then
    return false
  end
  return true
end

function C:isAppActive(app)
  if not self:isAppOpen(app) then
    return false
  end
  if self.WindowList:Find(function(l) return l.appType == app end).activeState == "Active" then
    return true
  end
  return false
end

