function C:Count()
  return self.WindowList.Count
end

function C:ActivateFirst()
  if self:Count() > 0 then
    do
      local num = self:Count() - 1
      while num >= 0 do
        IDX(self.WindowList, num):setInActive()
        num = num - 1
      end
    end
    self.WindowList:Last():setActive()
  end
end

function C:Touched(w)
  if self._windowList:Contains(w) and (not self:isAppOpen("EndingDialog") or w.appType == "EndingDialog") then
    if w.windowState == "minimized" then
      self:Pop(w)
    end
    if self._windowList:Remove(w) then
      self._windowList:Add(w)
      self:SetForeground(w)
    end
    self:ActivateFirst()
  end
end

function C:SetForeground(w)
  local orderInLayer = w.OrderInLayer
  for _, window in EACH(self._windowList) do
    if window.OrderInLayer >= orderInLayer then
      window:SetOrderInLayer(Mathf.Clamp(window.OrderInLayer - 1, 1, 30))
    end
  end
  w:SetOrderInLayer(40)
end

function C:CloseApp(app)
  if self:isAppOpen(app) then
    self:Close(self:GetWindowFromApp(app))
  end
end

function C:MinifyApp(app)
  if self:isAppOpen(app) then
    self:Minimize(self:GetWindowFromApp(app))
  end
end

function C:Close(w)
  w:Close()
  self._windowList:Remove(w)
  local taskbarByWindow = self:getTaskbarByWindow(self._taskBarList, w)
  self._taskBarList:Remove(taskbarByWindow)
  taskbarByWindow:Close()
  AudioManager:PlaySeByType("SE_window_close", false)
  self:ActivateFirst()
end

function C:getTaskbarByWindow(list, w)
  return list:Find(function(t) return t.window.Wname == w.Wname end)
end

function C:Minimize(w)
  w:Minimize()
  local taskbarByWindow = self:getTaskbarByWindow(self._taskBarList, w)
  if not (taskbarByWindow == nil) then
    taskbarByWindow:Minimize()
    AudioManager:PlaySeByType("SE_pirodown", false)
  end
end

function C:Pop(w)
  w:Pop()
  local taskbarByWindow = self:getTaskbarByWindow(self._taskBarList, w)
  if not (taskbarByWindow == nil) then
    taskbarByWindow:Pop()
    self:Touched(w)
    AudioManager:PlaySeByType("SE_kari", false)
  end
end

